import pytest
from pathlib import Path
from solution import evaluate

def test_add(): assert evaluate("1 + 2") == pytest.approx(3)
def test_precedence(): assert evaluate("2 + 3 * 4") == pytest.approx(14)
def test_parentheses(): assert evaluate("(2 + 3) * 4") == pytest.approx(20)
def test_true_division(): assert evaluate("10 / 4") == pytest.approx(2.5)
def test_left_assoc_minus(): assert evaluate("  7-2-1 ") == pytest.approx(4)
def test_left_assoc_div(): assert evaluate("8 / 2 / 2") == pytest.approx(2)
def test_power_right_assoc(): assert evaluate("2 ^ 3 ^ 2") == pytest.approx(512)
def test_unary_minus_binds_looser_than_power(): assert evaluate("-2 ^ 2") == pytest.approx(-4)
def test_unary_after_operator(): assert evaluate("2 * -3") == pytest.approx(-6)
def test_double_unary(): assert evaluate("--3") == pytest.approx(3)
def test_decimals(): assert evaluate("3.5 * 2") == pytest.approx(7)
def test_nested_parens(): assert evaluate("((1))") == pytest.approx(1)
def test_mixed(): assert evaluate("2 * (3 + 4) ^ 2 / 7 - -1") == pytest.approx(15)
@pytest.mark.parametrize("bad", ["", "   ", "2 +", "(1 + 2", "1 + 2)", "2 $ 3", "1 2", "1.2.3", "* 3"])
def test_invalid_raises_value_error(bad):
    with pytest.raises(ValueError): evaluate(bad)
def test_division_by_zero_is_value_error():
    with pytest.raises(ValueError): evaluate("1 / (2 - 2)")
def test_no_eval_or_ast():
    import re
    src = Path("solution.py").read_text()
    for pat in (r"(?<![\w.])eval\(", r"(?<![\w.])exec\(", r"(?<![\w.])compile\(", r"\bimport ast\b", r"\bfrom ast\b", "sympy", "numexpr"):
        assert not re.search(pat, src), f"must not use {pat}"
